function openLogin(){document.getElementById('loginModal')?.classList.add('open');document.getElementById('loginError').textContent='';}
function closeLogin(){document.getElementById('loginModal')?.classList.remove('open')}
function openSignup(){closeLogin();document.getElementById('signupModal')?.classList.add('open');document.getElementById('signupError').textContent=''}
function closeSignup(){document.getElementById('signupModal')?.classList.remove('open')}
async function loginSubmit(e){e.preventDefault();const form=e.target;const identifier=form.identifier.value.trim();const password=form.password.value;const err=document.getElementById('loginError');err.textContent='';try{const r=await api('/auth/login',{method:'POST',body:JSON.stringify({identifier,password})});localStorage.setItem('fsToken',r.data.token);localStorage.setItem('fsUser',JSON.stringify(r.data.user));const role=r.data.user.role;location.href=role==='FARMER'?'farmer-dashboard.html':role==='OPERATOR'?'operator-dashboard.html':role==='LOGISTICS'?'logistics-dashboard.html':'admin-dashboard.html'}catch(x){err.textContent=x.message}}
let pendingSignup={};
async function requestSignupOtp(e){e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));const err=document.getElementById('signupError');err.textContent='';if(!/^[6-9]\d{9}$/.test(data.phone)){err.textContent='Enter a valid 10-digit Indian mobile number.';return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)){err.textContent='Enter a valid email address.';return}if(!/^(?=.*[A-Za-z])(?=.*\d)(?=.*[^A-Za-z\d]).{8,}$/.test(data.password)){err.textContent='Password must be 8+ characters with a letter, number and special character.';return}pendingSignup=data;try{const r=await api('/auth/request-otp',{method:'POST',body:JSON.stringify({phone:data.phone,email:data.email,purpose:'REGISTER'})});document.getElementById('otpDemo').textContent=r.data.demoOtp?`Demo OTP: ${r.data.demoOtp}`:'OTP sent to your registered contact.';document.getElementById('signupStep1').classList.add('hidden');document.getElementById('signupStep2').classList.remove('hidden')}catch(x){err.textContent=x.message}}
async function verifySignupOtp(e){e.preventDefault();const otp=e.target.otp.value.trim();const err=document.getElementById('signupError');try{const r=await api('/auth/verify-otp',{method:'POST',body:JSON.stringify({phone:pendingSignup.phone,email:pendingSignup.email,otp,purpose:'REGISTER'})});const p={...pendingSignup,otp,otpVerified:true};const rr=await api('/auth/register',{method:'POST',body:JSON.stringify(p)});localStorage.setItem('fsToken',rr.data.token);localStorage.setItem('fsUser',JSON.stringify(rr.data.user));location.href='farmer-dashboard.html'}catch(x){err.textContent=x.message}}
async function ensureDemoAuth(role){
  const demoAccounts = {
    FARMER: {identifier: 'farmer@fasalsetu.demo', password: 'Farmer@123'},
    OPERATOR: {identifier: 'operator@fasalsetu.demo', password: 'Operator@123'},
    LOGISTICS: {identifier: 'logistics@fasalsetu.demo', password: 'Logistics@123'},
    ADMIN: {identifier: 'admin@fasalsetu.demo', password: 'Admin@123'}
  };
  const creds = demoAccounts[role] || demoAccounts.FARMER;
  try {
    const apiBase = localStorage.getItem('fsApi') || 'http://localhost:5000/api';
    const res = await fetch(apiBase + '/auth/login', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(creds)
    });
    const data = await res.json();
    if(data.success && data.data?.token) {
      localStorage.setItem('fsToken', data.data.token);
      localStorage.setItem('fsUser', JSON.stringify(data.data.user));
      return data.data.user;
    }
  } catch(e){}
  return null;
}
function logout(){localStorage.removeItem('fsToken');localStorage.removeItem('fsUser');location.href='index.html'}
function requireRole(role, autoRedirect = true){
  let u = null;
  try { u = JSON.parse(localStorage.getItem('fsUser')||'null'); } catch(e){}
  const token = localStorage.getItem('fsToken');
  if(!u || !token || u.role !== role){
    if(autoRedirect){
      location.href = 'index.html?login=1';
    }
    return null;
  }
  return u;
}
function setupNav(){ensureAuthModals();document.getElementById('menu')?.addEventListener('click',()=>document.getElementById('navLinks')?.classList.toggle('open'));document.querySelectorAll('[data-login]').forEach(b=>b.addEventListener('click',openLogin));document.querySelectorAll('[data-signup]').forEach(b=>b.addEventListener('click',openSignup));const q=new URLSearchParams(location.search);if(q.get('login')==='1')setTimeout(openLogin,150);setLanguage(state.lang)}
function setupFaq(){document.querySelectorAll('.faq-q').forEach(b=>b.addEventListener('click',()=>b.closest('.faq-item').classList.toggle('open')))}
function handleBookSlot(centreId){const token=localStorage.getItem('fsToken');const userStr=localStorage.getItem('fsUser');let user=null;try{if(userStr)user=JSON.parse(userStr);}catch(e){}if(token&&user&&user.role==='FARMER'){window.location.href=`farmer-dashboard.html?centreId=${encodeURIComponent(centreId)}`;}else{openLogin();}}
async function loadPublicCentres(){const box=document.getElementById('centreList');if(!box)return;const query=()=>{const p=new URLSearchParams();const q=document.getElementById('centreSearch')?.value.trim();const s=document.getElementById('centreState')?.value;const c=document.getElementById('centreCrop')?.value;const st=document.getElementById('centreStatus')?.value;if(q)p.set('q',q);if(s)p.set('state',s);if(c)p.set('crop',c);if(st)p.set('status',st);return api('/public/centres?'+p.toString())};const render=async()=>{box.innerHTML='<div class="empty">⏳ Loading centres…</div>';try{const r=await query();box.innerHTML=r.data.length?r.data.map(c=>`<article class="list-item" style="padding:22px;background:#ffffff;border:1px solid rgba(21,71,52,0.12);border-radius:16px;box-shadow:0 4px 14px rgba(0,0,0,0.04);margin-bottom:16px;transition:all 0.2s hover:shadow-md"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:8px"><div><h3 style="margin:0 0 4px 0;font-size:1.15rem;font-weight:700;color:var(--green-950)">🏢 ${esc(c.name)}</h3><p style="margin:0;font-size:0.875rem;color:var(--ink-soft)">📍 Code: <strong>${esc(c.centreCode)}</strong> · ${esc(c.location?.district||'')} district, ${esc(c.location?.state||'')}</p></div><span class="status-pill ${c.status==='ACTIVE'?'status-active':'status-warn'}" style="font-weight:700">${c.status==='ACTIVE'?'🟢 ACTIVE':'🟡 PAUSED'}</span></div><div class="metric-row" style="margin:16px 0;padding:12px 16px;background:var(--paper);border-radius:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px"><div class="metric"><small style="color:var(--ink-soft);font-size:0.75rem;text-transform:uppercase">👥 Live Queue</small><strong style="color:var(--green-800);font-size:1.1rem">${c.liveQueue||0} <span style="font-size:0.75rem;font-weight:normal">farmers</span></strong></div><div class="metric"><small style="color:var(--ink-soft);font-size:0.75rem;text-transform:uppercase">⏱️ Est. Wait</small><strong style="color:var(--gold-dark,#b48312);font-size:1.1rem">${c.estimatedWait||0} <span style="font-size:0.75rem;font-weight:normal">min</span></strong></div><div class="metric"><small style="color:var(--ink-soft);font-size:0.75rem;text-transform:uppercase">🗓️ Daily Capacity</small><strong style="color:var(--green-950);font-size:1.1rem">${c.capacity?.slots||0} <span style="font-size:0.75rem;font-weight:normal">slots</span></strong></div></div><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:8px"><span style="font-size:0.825rem;color:var(--ink-soft)">🏛️ Govt. Authorised Mandi / Storage</span><button type="button" class="btn btn-primary btn-small" onclick="handleBookSlot('${c._id||c.id||''}')" style="padding:8px 18px;font-size:0.875rem;font-weight:600;border-radius:999px">✨ Book Slot Here →</button></div></article>`).join(''):'<div class="empty">No matching procurement centres found.</div>'}catch(e){box.innerHTML=`<div class="notice">⚠️ Unable to load centres. Make sure the Fasal Setu backend is running.</div>`}};['centreSearch','centreState','centreCrop','centreStatus'].forEach(id=>document.getElementById(id)?.addEventListener('input',render));render()}
async function loadCrops(){const box=document.getElementById('cropList');if(!box)return;const getCropImage=(name)=>{const n=(name||'').toLowerCase();if(n.includes('wheat'))return 'assets/crops/wheat.jpg';if(n.includes('mustard'))return 'assets/crops/mustard.jpg';if(n.includes('paddy')||n.includes('rice'))return 'assets/crops/paddy.jpg';if(n.includes('gram')||n.includes('chana'))return 'assets/crops/gram.jpg';if(n.includes('bajra')||n.includes('millet'))return 'assets/crops/bajra.jpg';if(n.includes('cotton'))return 'assets/crops/cotton.jpg';return 'assets/crops/wheat.jpg'};try{const r=await api('/public/crops');box.innerHTML=r.data.map(c=>`<article class="feature-card crop-card" style="display:flex;flex-direction:column;justify-content:space-between;padding:0;background:#ffffff;border:1px solid rgba(21,71,52,0.14);border-radius:18px;overflow:hidden;box-shadow:0 4px 14px rgba(0,0,0,0.04);transition:all 0.25s hover:-translate-y-1 hover:shadow-md"><div style="position:relative;width:100%;height:165px;overflow:hidden;background:#e9efe9"><img src="${getCropImage(c.name)}" alt="${esc(c.name)}" style="width:100%;height:100%;object-fit:cover;transition:transform 0.3s ease"><div style="position:absolute;top:12px;right:12px;background:rgba(15,48,34,0.85);backdrop-filter:blur(6px);color:#ffffff;padding:4px 12px;border-radius:999px;font-size:0.75rem;font-weight:700">🗓️ ${esc(c.season)} Season</div></div><div style="padding:20px;display:flex;flex-direction:column;flex:1"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px"><h3 style="font-size:1.3rem;font-weight:700;color:var(--green-950);margin:0">${esc(c.name)}</h3><span style="font-size:0.75rem;background:rgba(237,163,53,0.15);color:var(--gold-dark,#b48312);padding:3px 8px;border-radius:6px;font-weight:700">📜 Govt. MSP</span></div><p style="font-size:0.85rem;color:var(--ink-soft);margin:0 0 16px 0">Official Minimum Support Price & Government Procurement Reference Rate</p><div style="background:var(--paper);padding:14px 16px;border-radius:14px;margin-bottom:20px;border:1px solid rgba(0,0,0,0.04);display:flex;justify-content:space-between;align-items:center"><div><small style="display:block;color:var(--ink-soft);font-size:0.75rem;text-transform:uppercase;letter-spacing:0.5px">Official MSP Rate</small><strong style="font-size:1.35rem;color:var(--green-900);font-weight:800">₹${Number(c.procurementRate).toLocaleString('en-IN')} <span style="font-size:0.85rem;font-weight:500;color:var(--ink-soft)">/ quintal</span></strong></div><div style="text-align:right"><span style="font-size:0.75rem;color:var(--green-800);background:rgba(21,71,52,0.08);padding:3px 8px;border-radius:6px;font-weight:600">✓ Guaranteed</span></div></div><div style="display:flex;gap:10px;margin-top:auto"><a href="msp-calculator.html" class="btn btn-outline btn-small" style="flex:1;text-align:center;justify-content:center;border-radius:999px">🧮 Calculate MSP</a><a href="procurement-centres.html" class="btn btn-primary btn-small" style="flex:1;text-align:center;justify-content:center;border-radius:999px">📍 Find Centres</a></div></div></article>`).join('')}catch(e){box.innerHTML='<div class="notice">Unable to load crops.</div>'}}
async function liveSearch(e){e.preventDefault();const id=document.getElementById('liveId').value.trim();const out=document.getElementById('liveResult');if(!id){out.innerHTML='<div class="notice">Enter a token or booking ID.</div>';return}try{const r=await api('/public/live-status/'+encodeURIComponent(id));const d=r.data;out.innerHTML=`<div class="card"><div class="eyebrow">LIVE PROCUREMENT STATUS</div><h2>🎫 ${esc(d.token||d.bookingId)}</h2><p><strong>🏢 ${esc(d.centre)}</strong> · 🌾 ${esc(d.crop||'')}</p><div class="metric-row"><div class="metric"><small>Status</small><strong>${esc(d.status)}</strong></div><div class="metric"><small>Farmers ahead</small><strong>👥 ${d.farmersAhead??'-'}</strong></div><div class="metric"><small>Estimated wait</small><strong>⏱️ ${d.estimatedWait??'-'} min</strong></div></div><p style="margin-top:15px;color:var(--ink-soft)">Last updated: ${new Date(d.updatedAt).toLocaleString('en-IN')}</p></div>`}catch(x){out.innerHTML=`<div class="notice">${esc(x.message)}</div>`}}
function calculateMSP(){const btn=document.getElementById('calcBtn');if(!btn)return;btn.addEventListener('click',async()=>{const crop=document.getElementById('calcCrop').value;const qty=Number(document.getElementById('calcQty').value);const out=document.getElementById('calcResult');if(!crop||!qty||qty<=0){out.innerHTML='<div class="notice">Select a crop and enter a quantity greater than 0.</div>';return}try{const r=await api('/public/calculate-msp?crop='+encodeURIComponent(crop)+'&quantity='+qty);const d=r.data;out.innerHTML=`<div class="result card" style="background:#ffffff;border:1px solid var(--gold);padding:24px;border-radius:18px;box-shadow:0 8px 24px rgba(237,163,53,0.12)"><div class="eyebrow" style="color:var(--gold-dark,#b48312)">✨ EXPECTED PROCUREMENT VALUE</div><div class="amount" style="font-size:2.2rem;font-weight:800;color:var(--green-950);margin:8px 0 16px 0">💰 ₹${Number(d.expectedPayment).toLocaleString('en-IN')}</div><div class="breakdown" style="background:var(--paper);padding:16px;border-radius:12px;display:flex;flex-direction:column;gap:10px"><div class="breakdown-row" style="display:flex;justify-content:space-between"><span>Selected Crop</span><strong>🌾 ${esc(d.crop)}</strong></div><div class="breakdown-row" style="display:flex;justify-content:space-between"><span>Quantity</span><strong>⚖️ ${qty} quintals</strong></div><div class="breakdown-row" style="display:flex;justify-content:space-between"><span>Official MSP Rate</span><strong>🏷️ ₹${Number(d.rate).toLocaleString('en-IN')} / qtl</strong></div><div class="breakdown-row" style="display:flex;justify-content:space-between"><span>Market Reference Rate</span><strong>📈 ₹${Number(d.marketReference).toLocaleString('en-IN')} / qtl</strong></div></div><div style="margin-top:16px;text-align:center"><a href="procurement-centres.html" class="btn btn-primary btn-block" style="border-radius:999px">📍 Find Centres Offering This Rate →</a></div></div>`}catch(x){out.innerHTML=`<div class="notice">${esc(x.message)}</div>`}})}
async function submitMessage(e){
  e.preventDefault();
  const f=e.target;
  const out=document.getElementById('messageResult');
  const payload = Object.fromEntries(new FormData(f));
  
  const name = String(payload.name||'').trim();
  const contact = String(payload.contact||payload.email||payload.phone||'').trim();
  const subject = String(payload.subject||'').trim();
  const msgText = String(payload.message||payload.body||'').trim();

  if(!name || name.length < 2){
    if(out) out.innerHTML = '<span style="color:#c6503e;font-weight:600">Please enter your full name (at least 2 characters).</span>';
    return;
  }
  if(!contact || contact.length < 5){
    if(out) out.innerHTML = '<span style="color:#c6503e;font-weight:600">Please enter a valid mobile number or email address.</span>';
    return;
  }
  if(!subject || subject.length < 2){
    if(out) out.innerHTML = '<span style="color:#c6503e;font-weight:600">Please enter a subject line.</span>';
    return;
  }
  if(!msgText || msgText.length < 5){
    if(out) out.innerHTML = '<span style="color:#c6503e;font-weight:600">Please enter your message (at least 5 characters).</span>';
    return;
  }

  try{
    await api('/public/messages',{method:'POST',body:JSON.stringify({name, contact, subject, message: msgText})});
    f.reset();
    if(out) out.innerHTML = '<span style="color:var(--green-800);font-weight:700">✓ Your message has been submitted successfully. Our team will contact you soon.</span>';
  }catch(x){
    if(out) out.innerHTML = `<span style="color:#c6503e;font-weight:600">⚠️ ${esc(x.message)}</span>`;
  }
}
document.addEventListener('DOMContentLoaded',()=>{setupNav();setupFaq();loadPublicCentres();loadCrops();liveSearch&&document.getElementById('liveForm')?.addEventListener('submit',liveSearch);calculateMSP();document.getElementById('messageForm')?.addEventListener('submit',submitMessage);document.getElementById('loginForm')?.addEventListener('submit',loginSubmit);document.getElementById('signupForm')?.addEventListener('submit',requestSignupOtp);document.getElementById('otpForm')?.addEventListener('submit',verifySignupOtp);observeDom()});
window.toggleLanguage=toggleLanguage;window.openLogin=openLogin;window.closeLogin=closeLogin;window.openSignup=openSignup;window.closeSignup=closeSignup;window.logout=logout;window.setLanguage=setLanguage;window.handleBookSlot=handleBookSlot;
